const update = $input.first()?.json || {};
const msg = update.message || update.edited_message || {};
const chat = msg.chat || {};
const rawText = String(msg.text || '').trim();
const chatId = String(chat.id || '').trim();
let action = '';
let prompt = '';
let task_id = '';
let executor = 'dry_run';
let endpoint = '';
if (/^\/run\b/i.test(rawText)) {
  action = 'run';
  prompt = rawText.replace(/^\/run\s*/i, '').trim() || 'Phase 3 smoke run';
} else if (/^\/codex\b/i.test(rawText)) {
  action = 'run';
  executor = 'codex';
  prompt = rawText.replace(/^\/codex\s*/i, '').trim() || 'Return TAC_CODEX_SMOKE_OK';
} else if (/^\/queue\b/i.test(rawText)) {
  action = 'queue';
  endpoint = 'queue';
  prompt = rawText.replace(/^\/queue\s*/i, '').trim() || 'Queued TAC runtime task';
} else if (/^\/handoff\b/i.test(rawText)) {
  action = 'handoff';
  endpoint = 'handoff';
} else if (/^\/status\b/i.test(rawText)) {
  action = 'status';
  task_id = rawText.replace(/^\/status\s*/i, '').trim();
} else if (/^\/killall\b/i.test(rawText)) {
  action = 'killall';
} else if (rawText && !rawText.startsWith('/')) {
  action = 'run';
  executor = 'codex';
  prompt = [
    'FOLLOWUP_TASK: true',
    'Telegram follow-up message. First inspect the latest TAC task/result if needed and continue from the most recent related bounded workspace.',
    'If this is an approval, execute only the approved bounded scope and keep forbidden live mutations blocked unless explicitly approved.',
    '',
    'User message:',
    rawText,
  ].join('\n');
}
function makeTaskId() {
  const stamp = new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
  const rand = Math.random().toString(16).slice(2, 10).padEnd(8, '0');
  return `tac-${stamp}-${rand}`;
}
if (action === 'run' && !task_id) {
  task_id = makeTaskId();
}
const supported = !!action && !!chatId;
endpoint = endpoint || (action === 'killall' ? 'killall' : action === 'status' ? 'status' : 'run');
return [{ json: { supported, action, endpoint, queue_mode: action === 'queue', handoff_mode: action === 'handoff', runner_url: `http://172.17.0.1:8765/${endpoint}`, prompt, task_id, chat_id: chatId, executor, received_text: rawText } }];

const response = $json || {};
const result = response.result || {};
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const status = String(result.status || (response.ok ? 'PASS' : 'UNKNOWN'));
const statusLabel = status === 'PASS' ? "\uc644\ub8cc" : status === 'BLOCKED' ? "\ub9c9\ud798" : status === 'FAIL' ? "\uc2e4\ud328" : status;
const taskId = String(result.task_id || response.task_id || $node['Normalize Telegram Command'].json.task_id || 'unknown');
const rawSummary = String(result.summary || response.message || response.error || "\ubcf4\uace0 \ub0b4\uc6a9\uc774 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.");
const cleanSummary = rawSummary
  .replace(/^\[[A-Z]+\].*reason=.*$/m, '')
  .replace(/Codex output:/g, "\uc0c1\uc138 \ubcf4\uace0:")
  .trim();
const summary = escapeHtml(cleanSummary.slice(0, 2850));
const text = [
  "[Kindred AI Controller]",
  "\uc0c1\ud0dc: " + statusLabel,
  "\uc791\uc5c5\ubc88\ud638: " + taskId,
  '',
  "\uacb0\uacfc \uc694\uc57d:",
  summary || "\uc791\uc5c5\uc740 \ub05d\ub0ac\uc9c0\ub9cc \uc694\uc57d\uc774 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.",
  '',
  "\ub2e4\uc74c\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uba85\ub839:",
  `/status ${taskId}`,
  '/killall'
].join('\n').slice(0, 3900);
return [{ json: { status, task_id: taskId, telegram_text: text, chat_id: $node['Normalize Telegram Command'].json.chat_id } }];

const command = $node['Normalize Telegram Command'].json || {};
const taskId = String(command.task_id || 'starting');
const raw = String(command.received_text || command.prompt || '').trim();
const isCodex = String(command.executor || '') === 'codex';
const isFollowup = raw && !raw.startsWith('/');
const hasWorkspace = /WORKSPACE\s*[:=]/i.test(raw) || /\/home\/ubuntu\/workspace\//.test(raw);
const lowerRaw = raw.toLowerCase();
const wantsLongRun = /(6\s*(hours?|hrs?)|six\s*hours?|overnight|all\s*day|60\s*minutes?|hourly)/i.test(lowerRaw);
const eta = wantsLongRun
  ? "\ucd5c\ub300 30\ubd84 \uc0ac\uc774\ud074\uc744 \ubaa8\ub450 \uc0ac\uc6a9\ud558\uace0, \uc791\uc5c5\uc7a5\ubd80\uc640 \ub2e4\uc74c \uc2e4\ud589 \uc778\uacc4\ub85c \uacc4\uc18d \uc774\uc5b4\uac11\ub2c8\ub2e4."
  : isCodex ? (raw.length > 500 ? "\uc57d 5~30\ubd84" : "\uc57d 1~5\ubd84") : "1\ubd84 \uc774\ub0b4";
const direction = wantsLongRun
  ? "\ub9c9\ud78c \ud56d\ubaa9\uc740 deferred gate\ub85c \uae30\ub85d\ud558\uace0, \uac00\ub2a5\ud55c \ub85c\uceec/\uc624\ud504\ub77c\uc778/\ud14c\uc2a4\ud2b8/\uc2a4\uce90\ud3f4\ub4dc \uc791\uc5c5\uc740 \uacc4\uc18d \uc9c4\ud589\ud569\ub2c8\ub2e4."
  : isFollowup
    ? "\uc774\uc804 \uc791\uc5c5\uc758 \uc774\uc5b4\uc11c \ud560 \uc77c\uc744 \ud655\uc778\ud558\uace0, \uac19\uc740 \ud504\ub85c\uc81d\ud2b8 \ubc94\uc704\uc5d0\uc11c \uacc4\uc18d \uc9c4\ud589\ud569\ub2c8\ub2e4."
    : isCodex
      ? "\ud504\ub85c\uc81d\ud2b8 \uc0c1\ud0dc\ub97c \ud655\uc778\ud55c \ub4a4, \uac00\ub2a5\ud55c \uc218\uc815\uacfc \uac80\uc99d\uc744 \uc9c4\ud589\ud558\uace0 \uacb0\uacfc\ub97c \ubcf4\uace0\ud569\ub2c8\ub2e4."
      : "\ucee8\ud2b8\ub864\ub7ec \uc0c1\ud0dc \ud655\uc778 \ub610\ub294 \uc9e7\uc740 \uc810\uac80\uc744 \uc2e4\ud589\ud569\ub2c8\ub2e4.";
const flow = [
  "HQ: \uc694\uccad\uc744 \ubaa9\ud45c, \uae08\uc9c0\uc0ac\ud56d, \uc6b0\uc120\uc21c\uc704\ub85c \uc815\ub9ac",
  "\uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130: \uc791\uc5c5\ubc88\ud638\ub97c \ub9cc\ub4e4\uace0 \uc2e4\ud589\uae30\ub85c \uc804\ub2ec",
  "Codex: \uc9c0\uc815\ub41c \uc791\uc5c5 \ud3f4\ub354 \uc548\uc5d0\uc11c\ub9cc \uc218\uc815\uacfc \uac80\uc99d \uc218\ud589",
  "\uac80\ud1a0 \ub2e8\uacc4: \uc131\uacf5, \uc2e4\ud328, \ub9c9\ud78c \uc774\uc720 \ud655\uc778",
  "\ubcf4\uace0 \ub2e8\uacc4: \uc644\ub8cc\ud55c \uc77c, \ubabb\ud55c \uc77c, \ub2e4\uc74c \ub2e8\uacc4\ub97c \ud55c\uad6d\uc5b4\ub85c \uc694\uc57d"
];
const plan = [
  hasWorkspace ? "\uc0ac\uc6a9\uc790\uac00 \uc9c0\uc815\ud55c \uc791\uc5c5 \ud3f4\ub354\uc5d0\uc11c \uc9c4\ud589\ud569\ub2c8\ub2e4." : "\uc774\uc804 \uc791\uc5c5 \ud3f4\ub354\ub97c \uc6b0\uc120 \uc0ac\uc6a9\ud558\uace0, \uc5c6\uc73c\uba74 \ucee8\ud2b8\ub864\ub7ec \uae30\ubcf8 \ud3f4\ub354\uc5d0\uc11c \uc9c4\ud589\ud569\ub2c8\ub2e4.",
  wantsLongRun ? "\uae34 \uc791\uc5c5\uc740 \uc911\ub2e8\uc774 \uc544\ub2c8\ub77c continuation ledger\uc640 \ub2e4\uc74c \uc2e4\ud589 \uc778\uacc4\ub85c \uc774\uc5b4\uac11\ub2c8\ub2e4." : "\uc774\ubc88 \uc694\uccad \ubc94\uc704 \uc548\uc5d0\uc11c \ubc14\ub85c \ud655\uc778\ud558\uace0 \uc2e4\ud589\ud569\ub2c8\ub2e4.",
  "\uba3c\uc800 \uba54\ubaa8\ub9ac\uc640 \ud604\uc7ac \uc0c1\ud0dc\ub97c \uc77d\uc2b5\ub2c8\ub2e4.",
  "\uc2e4\uc81c \uc8fc\ubb38, \ucde8\uc18c, \uc7ac\uc8fc\ubb38, \ube44\ubc00\uac12 \ucd9c\ub825, Docker \uc7ac\uc2dc\uc791, \uc6b4\uc601 \ubc18\uc601\uc740 \ub9c9\uc2b5\ub2c8\ub2e4.",
  "\uac00\ub2a5\ud55c \ud14c\uc2a4\ud2b8\uc640 \uac80\uc99d\uc744 \ub3cc\ub9bd\ub2c8\ub2e4.",
  "\ub05d\ub098\uba74 \uc644\ub8cc\ud55c \uc77c, \ubabb\ud55c \uc77c, \ub0a8\uc740 \uc77c, \ud544\uc694\ud55c \uc2b9\uc778\uc744 \ubcf4\uace0\ud569\ub2c8\ub2e4."
];
const text = [
  "[Kindred AI Controller]",
  "\uc0c1\ud0dc: \uc811\uc218\ub428",
  "\uc791\uc5c5\ubc88\ud638: " + taskId,
  '',
  "\uc608\uc0c1 \uc2dc\uac04: " + eta,
  '',
  "\uc9c4\ud589 \ubc29\ud5a5:",
  direction,
  '',
  "\uc5ed\ud560 \ubd84\ub2f4:",
  ...flow.map(x => `- ${x}`),
  '',
  "\uc9c4\ud589 \uacc4\ud68d:",
  ...plan.map(x => `- ${x}`),
  '',
  "\ud655\uc778 \uba85\ub839:",
  `/status ${taskId}`,
  '/killall'
].join('\n').slice(0, 3900);
return [{ json: { chat_id: command.chat_id, telegram_text: text } }];
